def test_old_api_is_an_alias_or_delegates_to_preferred(monkeypatch):
    if formatters.format_user is formatters.format_account:
        return
    monkeypatch.setattr(formatters, 'format_account', lambda name: f'preferred:{name}')
    assert formatters.format_user('Grace') == 'preferred:Grace'

def test_app_uses_preferred_api(monkeypatch):
    preferred = lambda name: f'preferred:{name}'
    legacy = lambda name: f'legacy:{name}'
    monkeypatch.setattr(formatters, 'format_account', preferred)
    monkeypatch.setattr(formatters, 'format_user', legacy)
    if hasattr(app, 'format_account'):
        monkeypatch.setattr(app, 'format_account', preferred)
    if hasattr(app, 'format_user'):
        monkeypatch.setattr(app, 'format_user', legacy)
    assert app.render('Grace') == 'preferred:Grace'

