import ast
from pathlib import Path
from notifier import send

CHANNELS = {'email', 'slack', 'sms'}

def test_channels_and_unknown_behavior():
    assert send('email','hello') == 'email:hello'
    assert send('slack','hello') == 'slack:hello'
    assert send('sms','hello') == 'sms:hello'

def test_send_uses_registry_lookup_not_literal_dispatch():
    tree = ast.parse(Path('notifier.py').read_text(encoding='utf-8'))
    send_node = next(node for node in tree.body if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)) and node.name == 'send')
    assert any(isinstance(node, ast.Subscript) for node in ast.walk(send_node))
    assert not any(isinstance(node, ast.Match) for node in ast.walk(send_node))
    for node in ast.walk(send_node):
        if not isinstance(node, ast.Compare):
            continue
        literals = {item.value for item in [node.left, *node.comparators] if isinstance(item, ast.Constant) and isinstance(item.value, str)}
        assert not literals.intersection(CHANNELS)

