from collections import OrderedDict

class TTLCache:
    def __init__(self, capacity, ttl_seconds, clock):
        if capacity <= 0:
            raise ValueError('capacity must be positive')
        self.capacity=capacity; self.ttl=ttl_seconds; self.clock=clock; self.data=OrderedDict()
    def _purge_expired(self):
        now=self.clock()
        for key, (_, expires) in list(self.data.items()):
            if now >= expires:
                del self.data[key]
    def get(self, key):
        item=self.data.get(key)
        if item is None: return None
        value, expires=item
        if self.clock() >= expires:
            del self.data[key]; return None
        self.data.move_to_end(key); return value
    def put(self, key, value):
        self._purge_expired()
        self.data.pop(key, None)
        self.data[key]=(value, self.clock()+self.ttl)
        while len(self.data) > self.capacity:
            self.data.popitem(last=False)

